struct MatOut {
    double G11, G12, G13, G22, G23, G33;
};

MatOut mat_isotropic(double E, double nu, double t) {
    MatOut m;
    double D = E * t*t*t / (12.0 * (1.0 - nu*nu));
    m.G11 = D;
    m.G12 = nu * D;
    m.G13 = 0.0;
    m.G22 = D;
    m.G23 = 0.0;
    m.G33 = D * (1.0 - nu) / 2.0;
    return m;
}

